"""
@package mocaxpy.MocaxDomain
MocaxDomain module.

Exports the MocaxDomain class.
"""

import ctypes
import mocaxpy.MocaxCInterface
import copy
import sys
from mocaxpy.MocaxException import *

if sys.version_info.major >= 3:
    long = int
    xrange = range


class MocaxDomain(object):
    """
    A Mocax domain.

    Encapsulates the boundaries of a Mocax function.
    """

    def __init__(self, domain):
        """
        Constructor from a bidimensional container (e.g., a list of lists, a tuple of tuples, a list of tuples...).

        @param[in] domain The domain boundaries. A container of containers (min: 1, max: 58) of length 2.
                          It's expected that each pair satisfies that domain_i_0 < domain_i_1.
                          Allowed types: @c list, @c tuple; allowed content types: @c list, @c tuple; containing @c int, @c long, @c float
        """

        # Validation
        if not isinstance(domain, (list, tuple)):
            raise TypeError("domain has to be a list or a tuple")
        for i in xrange(len(domain)):
            if not isinstance(domain[i], (list, tuple)):
                raise TypeError("Subdomain " + str(i) + " of domain has to be a list or a tuple")
            for j in xrange(len(domain[i])):
                if not isinstance(domain[i][j], (int, long, float, str)):
                    raise TypeError("End " + str(j) + " of subdomain " + str(i)
                                    + " of domain has to be a number or a string parsable to a real number")

        temp_domain = []
        for i in xrange(len(domain)):
            entry = []
            for j in xrange(len(domain[i])):
                entry.append(float(domain[i][j]))
            temp_domain.append(entry)
        domain = temp_domain

        if len(domain) < 1:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_NOT_ALLOWED, "The domain dimensionality cannot be less than 1. len(domain) = "
                                 + str(len(domain)))
        i = 0
        for subdomain in domain:
            if len(subdomain) != 2:
                raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_INCOMPLETE_DOMAIN, "One of the subdomains isn't correctly defined. len(domain["
                                     + str(i) + "]) = " + str(len(subdomain)))
            if subdomain[0] >= subdomain[1]:
                raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_X_MAX_LOWER_OR_EQUAL_THAN_X_MIN, "The domain has one of its higher boundaries lower or equal "
                                     + "than its corresponding lower. domain[" + str(i) + "][0] >= domain["
                                     + str(i) + "][1]; " + str(subdomain[0]) + " >= " + str(subdomain[1]))
            i += 1

        # Construction
        self.__setup(len(domain))
        self.__domain = domain

    def get_num_dimensions(self):
        """
        Gets the number of dimensions of this domain.

        @return The number of dimensions of the domain.
                Return type: @c int
        """

        return self.__num_dimensions

    def get_x_min(self, dimension):
        """
        Gets the lower end of the domain in a given dimension.

        @param[in] dimension The index (0-based) of the dimension which lower end is to be obtained.
                             An integer number in the range [0,getNumDimensions()).
                             Allowed types: @c int, @c long
        @return The lower end of the domain in the given dimension.
                Return type: @c float
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parsable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, "
                             + str(self.get_num_dimensions() - 1) + "]")
        return self.__get_x(dimension, 0)

    def get_x_max(self, dimension):
        """
        Gets the higher end of the domain in a given dimension.

        @param[in] dimension The index (0-based) of the dimension which higher end is to be obtained.
                             An integer number in the range [0,getNumDimensions()).
                             Allowed types: @c int, @c long
        @return The higher end of the domain in the given dimension.
                Return type: @c float
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parsable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, "
                             + str(self.get_num_dimensions() - 1) + "]")
        return self.__get_x(dimension, 1)

    def get_width(self, dimension):
        """
        Gets the width of the domain in a given dimension
        (the difference between the lowest and highest ends of the domain in that dimension).

        @param[in] dimension The index (0-based) of the dimension which width is to be obtained.
                             An integer number in the range [0,getNumDimensions()).
                             Allowed types: @c int, @c long
        @return The width of the domain in the given dimension.
                Return type: @c float
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parsable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, "
                             + str(self.get_num_dimensions() - 1) + "]")
        return self.get_x_max(dimension) - self.get_x_min(dimension)

    def export_as_multidimensional_array(self):
        """
        Exports the domain as a bidimensional C array.

        @note This method is meant to be used internally. For a Python-friendly approach, use export_as_list() instead.

        @return A C-friendly structure containing the domain.
                Return type: <tt>ctypes.POINTER(ctypes.c_double)</tt>
        """

        val = (ctypes.POINTER(ctypes.c_double) * len(self.__domain))()
        for i,v in enumerate(self.__domain):
            val[i] = (ctypes.c_double * len(v))(*v)
        return val

    def export_as_list(self):
        """
        Exports the domain as a native Python list.

        @return A list containing every domain boundary.
                Return type: @c list
        """

        return copy.deepcopy(self.__domain)

    def __str__(self):
        """
        Gets a string representation of this domain.
        @return The domain in string format.
                Return type: @c str
        """
        return str(self.export_as_list())

    def __init(self):
        self.__num_dimensions = 0
        self.__domain = None

    def __setup(self, num_dimensions):
        self.__init()

        self.__num_dimensions = num_dimensions
        self.__domain = list([0.0, 0.0] * self.__num_dimensions)

    def __get_x(self, dimension, end):
        return self.__domain[dimension][end]
